import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Δοκιμαστικές λειτουργίες AADE/myDATA και EDXEIX","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/regulatory-sandbox.md","filePath":"el/integrations/regulatory-sandbox.md"}'),o={name:"el/integrations/regulatory-sandbox.md"};function l(n,a,s,d,c,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="δοκιμαστικες-λειτουργιες-aade-mydata-και-edxeix" tabindex="-1">Δοκιμαστικές λειτουργίες AADE/myDATA και EDXEIX <a class="header-anchor" href="#δοκιμαστικες-λειτουργιες-aade-mydata-και-edxeix" aria-label="Permalink to &quot;Δοκιμαστικές λειτουργίες AADE/myDATA και EDXEIX&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="πεδιο" tabindex="-1">Πεδίο <a class="header-anchor" href="#πεδιο" aria-label="Permalink to &quot;Πεδίο&quot;">​</a></h2><p>Υλοποιούνται μόνιμες εγγραφές και ιστορικό προσπαθειών για δοκιμαστική προετοιμασία. Η ζωντανή κανονιστική υποβολή αποκλείεται ρητά στον ελεγμένο κώδικα. Δοκιμαστική εγγραφή ή αναφορά δεν αποτελεί επίσημη υποβολή, νόμιμο έγγραφο ή πιστοποίηση συμμόρφωσης.</p><h2 id="εξουσιοδοτημενη-δοκιμαστικη-ροη" tabindex="-1">Εξουσιοδοτημένη δοκιμαστική ροή <a class="header-anchor" href="#εξουσιοδοτημενη-δοκιμαστικη-ροη" aria-label="Permalink to &quot;Εξουσιοδοτημένη δοκιμαστική ροή&quot;">​</a></h2><ol><li>Επιβεβαιώστε εταιρεία, τιμολόγιο ή κράτηση, δικαίωμα χρήστη και συνθετικό περιβάλλον.</li><li>Για AADE/myDATA προετοιμάστε δοκιμαστική εγγραφή από επιλέξιμο τιμολόγιο με δικαίωμα εγγραφής τιμολογίων. Ελέγξτε έγγραφο και ιστορικό με υπεύθυνο λογιστή/διαχειριστή.</li><li>Για EDXEIX χρησιμοποιήστε εξουσιοδοτημένη ροή ανάθεσης για δοκιμαστική έκδοση στη σωστή κράτηση και σκέλος. Ελέγξτε υποστηριζόμενη παράταση/ακύρωση. Η πρόσβαση οδηγών περιορίζεται· μην χρησιμοποιείτε ανάθεση άλλου οδηγού ή εταιρείας.</li><li>Επιβεβαιώστε εγγραφή και ιστορικό. Μην παρουσιάζετε δοκιμαστικό αποτέλεσμα ως επίσημη αναφορά, άδεια λειτουργίας ή φορολογική υποβολή.</li><li>Αν αποκλειστεί ζωντανή προσπάθεια, διατηρήστε το καταγεγραμμένο αποτέλεσμα και ακολουθήστε εγκεκριμένη χειροκίνητη νόμιμη διαδικασία. Μην παρακάμπτετε τον αποκλεισμό.</li></ol><p>Πριν από μελλοντική ζωντανή ενεργοποίηση απαιτούνται ισχύουσες επίσημες προδιαγραφές, διαπιστευτήρια, ιδιοκτησία λογαριασμού, νομικός/λογιστικός έλεγχος, δικαιώματα, πραγματική αποδοχή και διαδικασία λειτουργίας. Δεν εγκρίνεται διαδικασία ζωντανών κλειδιών για αυτή την έκδοση.</p><p>Δείτε <a href="/el/integrations/third-party-api-setup.html">API τρίτων</a> και <a href="/el/security-privacy/">Ασφάλεια</a>.</p>',8)])])}const _=e(o,[["render",l]]);export{m as __pageData,_ as default};
